<template><div class="portal-page"><header><h1>Perfil</h1><p>Tu cuenta y configuración de seguridad</p></header><div v-if="profile" class="grid"><section class="card"><h2>{{profile.client&&profile.client.name}}</h2><dl><div><dt>Correo del portal</dt><dd>{{profile.portal_email}}</dd></div><div><dt>Cliente</dt><dd>{{profile.client&&profile.client.name}}</dd></div><div><dt>Correo electrónico</dt><dd>{{profile.client&&profile.client.email||'—'}}</dd></div><div><dt>Teléfono</dt><dd>{{profile.client&&profile.client.phone||'—'}}</dd></div><div><dt>Dirección</dt><dd>{{profile.client&&profile.client.adresse||'—'}}</dd></div></dl></section><section class="card"><h2>Cambiar contraseña</h2><p>Usa al menos 8 caracteres</p><form @submit.prevent="changePassword"><label>Contraseña actual<input v-model="currentPassword" type="password" required></label><label>Nueva contraseña<input v-model="newPassword" type="password" required minlength="8" placeholder="Mínimo 8 caracteres"></label><label>Confirmar nueva contraseña<input v-model="confirmPassword" type="password" required></label><p v-if="pwError" class="error">{{pwError}}</p><p v-if="pwSuccess" class="success">Contraseña actualizada correctamente.</p><button type="submit" :disabled="pwLoading">{{pwLoading?'Actualizando...':'Actualizar contraseña'}}</button></form></section></div><div v-else class="loading">Cargando perfil...</div></div></template>
<script>export default{data(){return{profile:null,currentPassword:'',newPassword:'',confirmPassword:'',pwError:'',pwSuccess:false,pwLoading:false}},mounted(){this.fetch()},methods:{async fetch(){try{const{data}=await axios.get('/portal/profile');this.profile=data}catch(_){}},async changePassword(){if(this.newPassword!==this.confirmPassword){this.pwError='Las contraseñas no coinciden';return}this.pwError='';this.pwSuccess=false;this.pwLoading=true;try{await axios.put('/portal/profile/password',{current_password:this.currentPassword,password:this.newPassword,password_confirmation:this.confirmPassword});this.pwSuccess=true;this.currentPassword=this.newPassword=this.confirmPassword=''}catch(e){const data=e?.response?.data||e;this.pwError=data?.message||'No se pudo actualizar la contraseña'}this.pwLoading=false}}}</script>
<style scoped>header{margin-bottom:1.25rem}h1{margin:0;font-size:1.5rem}header p{color:var(--pc-text-muted)}.grid{display:grid;grid-template-columns:1fr 1fr;gap:1.25rem}.card{background:var(--pc-surface);border:1px solid var(--pc-border);border-radius:var(--pc-radius);padding:1.35rem}.card h2{margin-top:0}dl div{display:flex;justify-content:space-between;gap:1rem;padding:.7rem 0;border-bottom:1px solid var(--pc-border)}dt{color:var(--pc-text-muted)}form{display:grid;gap:1rem}label{display:grid;gap:.4rem;font-weight:600}input{padding:.65rem;border:1px solid var(--pc-border-strong);border-radius:8px}button{padding:.65rem 1rem;background:var(--pc-primary);color:#fff;border:0;border-radius:8px}.error{color:var(--pc-danger)}.success{color:var(--pc-success)}.loading{padding:3rem;text-align:center}@media(max-width:768px){.grid{grid-template-columns:1fr}}</style>